void CallOneTimes::run()
{
	
	while (!isInterruptionRequested())
	{
		if (isInterruptionRequested())      // ⬅️ 每轮查一次
			return;
		if (_threadstatus == CallOneTimes::SYS_CALIBRATE_SAVE)
		{
			//ThreadStatus = CallOneTimes::SYS_CAMERA_STOP_COLLECT;		int result = pcl::io::savePLYFile("D:/project/PolePieceMeasure/PolePieceMeasureWin/x64/Release/ply/20251118.ply", cloud2, Eigen::Vector4f::Zero(), Eigen::Quaternionf::Identity(), false, false);

			ThreadStatus = CallOneTimes::SYS_CALIBRATE_SAVE;
			_threadstatus = -1;
		}
		switch (ThreadStatus)
		{
		case CallOneTimes::SYS_NOWORK:
		{
			QThread::msleep(100);//线程空跑 
		}
			break;
		case CallOneTimes::SYS_CAMERA_START_COLLECT:
		{
			if ((status = GoSystem_SetDataHandler(system, onData, &contextPointer)) != kOK)
			{
				emit onsendStatus(QStringLiteral("注册图像回调失败"));
				ThreadStatus = CallOneTimes::SYS_NOWORK;
			}
			// start Gocator sensor
			if ((status = GoSystem_Start(system)) != kOK)
			{
 				emit onsendStatus(QStringLiteral("开始采集失败"));
				ThreadStatus = CallOneTimes::SYS_NOWORK;
			}
			else
			{
				emit onsendStatus(QStringLiteral("开始采集"));

			}
			ThreadStatus = CallOneTimes::SYS_NOWORK;
		}
			break;
		case CallOneTimes::SYS_CAMERA_STOP_COLLECT:
		{
 			if ((status = GoSystem_Stop(system)) != kOK)
			{
 				emit onsendStatus(QStringLiteral("停止采集失败"));
				return;
			}
			emit onsendStatus(QStringLiteral("停止采集"));
			ThreadStatus = CallOneTimes::SYS_NOWORK;
		}
		    break;
		case CallOneTimes::SYS_CALIBRATE_SAVE:
		{ 
			CreateWorkDir(_callOneTimesMainWork);
			cloudsResultDeal = pcl::PointCloud<pcl::PointXYZ>::Ptr(new pcl::PointCloud<pcl::PointXYZ>); 
			QString path = SavePath + QStringLiteral("/") + QStringLiteral("1.ply");
			int result = pcl::io::savePLYFileBinary(path.toStdString(), *cloudsResult);
			cloudsResultDeal = cloudsResult; 
			emit onsendStatus(QStringLiteral("点云保存成功"));
			emit onsendCloudDeal();
 			ThreadStatus = CallOneTimes::SYS_NOWORK;
		}
		break;
		default:
			break;
		}

    } 
} 	  
void CallOneTimes::CreateWorkDir(QString mainDir)
{
	QDateTime date = QDateTime::currentDateTime();
	//QString strWorkName = QStringLiteral("CL2407221123");//test
	QString strWorkName = QStringLiteral("HG") + date.toString("yyMMddHHmmss");
	_callOneTimesWork = mainDir + QStringLiteral("/") + strWorkName;
	QString pointDir = _callOneTimesWork + QStringLiteral("/") + QStringLiteral("pointCloud");
	QDir dir;//创建空目录，如果已存在，则删除后创建
	if (!dir.exists(_callOneTimesWork)) {
		dir.mkpath(_callOneTimesWork);
	}
	else {
		if (!dir.exists(_callOneTimesWork))
			dir.mkpath(_callOneTimesWork);
	}
	dir.mkpath(pointDir);
	SavePath = pointDir;
}
 

//通信----
 bool CallOneTimes::recvExact(int bytesNeeded)
{
	while (m_sock->bytesAvailable() < bytesNeeded) {
		if (!m_sock->waitForReadyRead(5000)) return false;
	}
	return true;
}
// finsclient.cpp
bool CallOneTimes::connectPLC(const QString& ip, quint16 port)
{
	//m_sock->connectToHost(ip, port);
	//if (!m_sock->waitForConnected(3000)) return false;
	///* ① 先发握手 TCP 头（16 字节全 0） */
	//m_sock->write(QByteArray(16, 0));
	//if (!m_sock->waitForBytesWritten()) return false;
	///* ② 等待 PLC 回 16 字节全 0 */
	//if (!m_sock->waitForReadyRead(3000)) return false;
	//if (m_sock->bytesAvailable() < 16) return false;
	//QByteArray ack = m_sock->read(16);
	//return ack == QByteArray(16, 0);
	m_sock->connectToHost(ip, port);
	if (!m_sock->waitForConnected(5000)) return false;

	m_sock->setSocketOption(QAbstractSocket::LowDelayOption, 1);

	/* 第一次握手：16 字节全 0 */
	if (m_sock->write(QByteArray(16, 0)) != 16) return false;
	if (!m_sock->waitForBytesWritten()) return false;

	/* 收 16 字节 */
	if (!recvExact(16)) return false;
	QByteArray ack = m_sock->read(16);
	if (ack != QByteArray(16, 0)) return false;

	/* 第二次握手：Command Frame */
	struct {
		uchar  header[4] = { 0x46,0x49,0x4E,0x53 }; // "FINS"
		uint32_t len = qToBigEndian(quint32(12)); // 后面 12 字节
		uint32_t cmd = qToBigEndian(quint32(0x00000000)); // Client connect
		uint32_t err = qToBigEndian(quint32(0x00000000));
		uint32_t clientNA = qToBigEndian(quint32(0x00000000)); // 可先填 0，让 PLC 分配
	} cmdFrame;

	if (m_sock->write(reinterpret_cast<const char*>(&cmdFrame), sizeof(cmdFrame)) != sizeof(cmdFrame))
		return false;
	if (!m_sock->waitForBytesWritten()) return false;

	/* 收 16 字节 Response Header */
	if (!recvExact(16)) return false;
	QByteArray respHdr = m_sock->read(16);
	uint32_t respLen = qFromBigEndian<uint32_t>(reinterpret_cast<const uchar*>(respHdr.constData() + 4));
	uint32_t respErr = qFromBigEndian<uint32_t>(reinterpret_cast<const uchar*>(respHdr.constData() + 8));
	if (respErr != 0) {
		qDebug() << "FINS/TCP connect error code" << Qt::hex << respErr;
		return false;
	}

	/* 后面可能还有 12 字节 body，继续收 */
	if (!recvExact(respLen - 4)) return false;
	QByteArray respBody = m_sock->read(respLen - 4);
	/* 解析 respBody 里的 clientNA 等，略 */

	return true;
}
bool CallOneTimes::disconnectPLC()
{
	bool s =m_sock->disconnect();
	return s;
}
QByteArray CallOneTimes::makeHeader(int finsLen)
{
	QByteArray h;
	int total = 8 + finsLen;
	h.append(char(total >> 24));   // 长度大端
	h.append(char(total >> 16));
	h.append(char(total >> 8));
	h.append(char(total));
	h.append(QByteArray(12, 0));   // 保留+命令+错误
	return h;
}
/* ---------- 把 0-255 转成 BCD 字节 ---------- */
static inline unsigned char toBCD(unsigned char v)
{
	Q_ASSERT(v <= 99);          // BCD 一个字节只能表示 0-99
	return ((v / 10) << 4) | (v % 10);
}
QByteArray CallOneTimes::makeWriteFrame(int start, const QVector<quint16>& values)
{
	const int words = values.size();
	QByteArray fins;

	/* -------- FINS 头 10 字节 -------- */
	fins.append(0x80);  // ICF
	fins.append(char(0));  // RSV
	fins.append(0x02);  // GCT
	fins.append(char(0));  // DNA
	fins.append(m_plcNode); // DA1
	fins.append(char(0));  // DA2
	fins.append(char(0));  // SNA
	fins.append(m_pcNode);  // SA1
	fins.append(char(0));  // SA2
	fins.append(char(0));  // SID

	/* -------- 命令码 0102 写内存 -------- */
	fins.append(0x01);
	fins.append(0x02);

	/* -------- 区域码 82 = DM -------- */
	fins.append(0x82);

	/* -------- 起始地址 3 BCD -------- */
	fins.append(char(toBCD(start / 10000)));
	fins.append(char(toBCD((start / 100) % 100)));
	fins.append(char(toBCD(start % 100)));

	/* -------- 写入数量 2 BCD -------- */
	fins.append(char(toBCD(words >> 8)));
	fins.append(char(toBCD(words & 0xFF)));

	/* -------- 数据区：每字 2 字节，大端 -------- */
	for (quint16 v : values) {
		fins.append(char(v >> 8));
		fins.append(char(v & 0xFF));
	}
	return fins;
}
bool CallOneTimes::waitForFrame(QByteArray& frame)
{
	frame.clear();

	/* 先收 16 字节 TCP 头 */
	while (m_sock->bytesAvailable() < 16) {
		if (!m_sock->waitForReadyRead(3000)) return false;
	}
	QByteArray head = m_sock->read(16);
	int totalLen = ((head[0] & 0xFF) << 24)
		| ((head[1] & 0xFF) << 16)
		| ((head[2] & 0xFF) << 8)
		| (head[3] & 0xFF);
	int finsLen = totalLen - 8;   // TCP 头 8 字节后面才是 FINS

	/* 再收剩余 finsLen 字节 */
	while (m_sock->bytesAvailable() < finsLen) {
		if (!m_sock->waitForReadyRead(3000)) return false;
	}
	frame = m_sock->read(finsLen);
	return true;
}
QByteArray CallOneTimes::makeReadFrame(int start, int words)
{
	QByteArray f;
	f.append(0x80);
 	f.append(char(0));
	f.append(0x02);
	f.append(char(0));                       // DNA
	f.append(m_plcNode);                  // DA1
	f.append(char(0));                       // DA2
	f.append(char(0));                       // SNA
	f.append(m_pcNode);                   // SA1
	f.append(char(0));                       // SA2
	f.append(char(0));                       // SID
	f.append(0x01); f.append(0x01);       // READ
	f.append(0x82);                       // DM 区
	// 起始地址 3 BCD
	f.append(char(toBCD(start >> 8)));
	f.append(char(toBCD(start & 0xFF)));
	f.append(char(0));
	// 数量 2 BCD
	f.append(char(toBCD(words >> 8)));
	f.append(char(toBCD(words & 0xFF)));
	return f;
}
bool CallOneTimes::readDM(int start, int words, QByteArray& data)
{
	QByteArray fins = makeReadFrame(start, words);
	QByteArray pack = makeHeader(fins.size()) + fins;
	m_sock->write(pack);
	if (!m_sock->waitForBytesWritten()) return false;

	QByteArray resp;
	if (!waitForFrame(resp)) return false;

	// 简单校验：长度、命令回显、结束码 0x0000
	if (resp.size() < 14 + words * 2) return false;
	if (resp.mid(10, 2) != QByteArray("\x01\x01")) return false;
	if (resp.mid(12, 2) != QByteArray("\x00\x00")) return false;
	data = resp.mid(14, words * 2);
	return true;
}
bool CallOneTimes::writeDM(int start, const QVector<quint16>& values)
{
	if (values.isEmpty()) return false;

	/* 1. 拼装 FINS 写命令帧（0102） */
	QByteArray fins = makeWriteFrame(start, values);

	/* 2. 加 16 字节 TCP 头 */
	QByteArray pack = makeHeader(fins.size()) + fins;

	/* 3. 发送 */
	m_sock->write(pack);
	if (!m_sock->waitForBytesWritten(3000)) return false;

	/* 4. 收完整应答 */
	QByteArray resp;
	if (!waitForFrame(resp)) return false;

	/* 5. 极简校验：命令回显 + 结束码 */
	if (resp.size() < 4) return false;
	// 命令码应回显 01 02
	if (resp[0] != char(1) || resp[1] != char(2)) return false;
	// 结束码 00 00 表示成功
	if (resp[2] != char(0) || resp[3] != char(0)) return false;

	return true;
}

void CallOneTimes::onTimeout()
{
	QByteArray raw;
	QVector<quint16> vs;
	if (readDM(1234, 1, raw)) {      // 读 DM1234
		quint16 v = (raw[0] & 0xFF) << 8 | (raw[1] & 0xFF);
		vs.push_back(v);
		emit valueChanged(vs);               // 抛回主线程
	}
}
